import{_ as t,c as a,o as e,a4 as _}from"./chunks/framework.DzOtv0XR.js";const m=JSON.parse('{"title":"后端同学是不是比前端同学理解业务更快？ - 知乎","description":"","frontmatter":{"kindle-sync":{"bookId":"20578","title":"(5 封私信 / 15 条消息) 后端同学是不是比前端同学理解业务更快？ - 知乎","author":"关于作者","highlightsCount":3}},"headers":[],"relativePath":"books/后端同学是不是比前端同学理解业务更快？ - 知乎.md","filePath":"books/后端同学是不是比前端同学理解业务更快？ - 知乎.md"}'),o={name:"books/后端同学是不是比前端同学理解业务更快？ - 知乎.md"},i=_('<h1 id="后端同学是不是比前端同学理解业务更快-知乎" tabindex="-1">后端同学是不是比前端同学理解业务更快？ - 知乎 <a class="header-anchor" href="#后端同学是不是比前端同学理解业务更快-知乎" aria-label="Permalink to &quot;后端同学是不是比前端同学理解业务更快？ - 知乎&quot;">​</a></h1><p>看业务类型</p><ul><li>消费、处理数据为主</li><li>交互为主</li></ul><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><p>比如我们做一个业务中台，对于后端来说，能看到数据的结构，如何定义权限，如何增删改查，如何聚合，如何打散，如何计算指标，这就是「业务」的全部内容。 — location: <a href="./.html">26</a> ^ref-40941</p><hr><p>对于大多数以消费数据为主的业务来说，可以看到完整数据的后端，比起只能看到部分接口数据的前端来说，有天然的优势。 造成这个局面的根本原因在于，很多的开发流程是从需求给到数据，数据到接口，接口到交互，FE 处于最末端。 如果是以消费交互为主的业务，比如游戏，可能前端反而要比后端更快理解业务。因为业务的核心是交互，前端掌控着完整的交互，而后端则是提供支持交互的各种数据，反而成了被动方。 — location: <a href="./.html">46</a> ^ref-36185</p><hr><p>此时需求是给到了交互，交互对接口提出要求，接口反推数据支持，FE 位于业务的中间核心。 — location: <a href="./.html">52</a> ^ref-12012</p><hr>',10),h=[i];function r(l,s,n,c,d,p){return e(),a("div",null,h)}const u=t(o,[["render",r]]);export{m as __pageData,u as default};
